// 自适应去噪内核
__global__ void adaptive_denoise(Image* image,
                                 float* noise_map,
                                 int x, int y,
                                 int patch_size) {
    // 计算局部噪声水平
    float local_noise = noise_map[y * image->width + x];

    // 根据噪声水平选择滤波策略
    if (local_noise > high_threshold) {
        // 高噪声区域：使用大窗口非局部均值
        int search_window = 21;
        nlm_filter_kernel<<<search_window * search_window, patch_size * patch_size>>>(
            image, x, y, patch_size, search_window
        );
    } else if (local_noise > low_threshold) {
        // 中等噪声：使用小窗口非局部均值
        int search_window = 7;
        nlm_filter_kernel<<<search_window * search_window, patch_size * patch_size>>>(
            image, x, y, patch_size, search_window
        );
    } else {
        // 低噪声：简单双边滤波
        bilateral_filter_kernel<<<1, patch_size * patch_size>>>(
            image, x, y, patch_size
        );
    }
}
```

